package com.crm.fees;
import com.crm.fees.entity.*;import com.crm.fees.repository.*;import com.crm.fees.service.*;import com.crm.security.AuthenticatedUserPrincipal;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class FeeBillingCandidatesTest {
 FeeRepository fees;FeeTimeRepository times;FeeOfferingRepository offerings;FeeBillingCandidates service;Fee fee;FeeTimeEntry time;FeeOffering offering;
 void role(String role){var roles=List.of(new SimpleGrantedAuthority("ROLE_"+role));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AuthenticatedUserPrincipal(42,"synthetic",roles),null,roles));}
 @BeforeEach void setup(){role("ADMIN");fees=mock(FeeRepository.class);times=mock(FeeTimeRepository.class);offerings=mock(FeeOfferingRepository.class);service=new FeeBillingCandidates(fees,times,offerings);fee=new Fee();fee.setId(11L);fee.setSourceTimeId(21L);fee.setCustomerId("101");fee.setCurrency("TND");fee.setServiceName("Consulting");fee.setExactHours(new BigDecimal("2.50"));fee.setHourlyRate(new BigDecimal("12.34"));fee.setAmount(new BigDecimal("30.85"));time=new FeeTimeEntry();time.setId(21L);time.setOfferingId(31L);time.setFeeId(11L);time.setHours(fee.getExactHours());time.setAppliedRate(fee.getHourlyRate());time.setAmount(fee.getAmount());offering=new FeeOffering();offering.setId(31L);offering.setCustomerId("101");offering.setCurrency("TND");when(fees.findById(11L)).thenReturn(Optional.of(fee));when(times.findById(21L)).thenReturn(Optional.of(time));when(offerings.findById(31L)).thenReturn(Optional.of(offering));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void immutableTimeLinkedCandidatePreservesAllExactSourceValues(){var c=service.get(11L);assertEquals("11",c.id());assertEquals("21",c.sourceTimeId());assertEquals("2.50",c.hours());assertEquals("30.85",c.amount());assertTrue(c.immutable());verify(fees,never()).save(any());verify(times,never()).save(any());}
 @Test void manualAndHistoricalFeesAreExcluded(){fee.setSourceTimeId(null);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.get(11));verifyNoInteractions(times,offerings);}
 @Test void cancelledOrMismatchedTimeCannotBecomeBillable(){time.setCancelled(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.get(11));time.setCancelled(false);time.setFeeId(12L);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.get(11));}
 @Test void freeStatusesAndCurrencyAreNotProof(){fee.setInvoiceStatus("BILLED");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.get(11));fee.setInvoiceStatus(null);offering.setCurrency("EUR");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.get(11));}
 @Test void changedAmountAndUnknownCustomerFailClosed(){fee.setAmount(new BigDecimal("30.86"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.get(11));fee.setAmount(new BigDecimal("30.85"));fee.setCustomerId(null);assertThrows(IllegalArgumentException.class,()->service.get(11));}
 @Test void personalRolesCannotReadCandidates(){for(String role:List.of("CLIENT","EMPLOYEE")){role(role);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.get(11));}verifyNoInteractions(fees);}
}
